<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('manage_locations');
$fields=['code','name','warehouse','floor_name','section_name','rack','shelf','shelf_bin'];
$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'add';try{if($action==='add'||$action==='update'){$vals=[];foreach($fields as $f)$vals[$f]=trim((string)($_POST[$f]??''));if($vals['code']===''||$vals['name']==='')throw new InvalidArgumentException('Location code and display name are required.');foreach($vals as $f=>$v)if(mb_strlen($v)>($f==='code'?40:($f==='name'||$f==='warehouse'?120:80)))throw new InvalidArgumentException('One of the values is too long.');if(!preg_match('/^[\x21-\x7E]+$/',$vals['code']))throw new InvalidArgumentException('Location code must use English letters, numbers and symbols only, with no spaces, so the rack label can be scanned.');$online=isset($_POST['online_fulfillment_enabled'])?1:0;if($action==='add'){$st=db()->prepare('INSERT INTO locations(code,name,warehouse,floor_name,section_name,rack,shelf,shelf_bin,online_fulfillment_enabled) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([...array_values($vals),$online]);audit('LOCATION_CREATE','location',(int)db()->lastInsertId());}else{$id=(int)($_POST['id']??0);$st=db()->prepare('UPDATE locations SET code=?,name=?,warehouse=?,floor_name=?,section_name=?,rack=?,shelf=?,shelf_bin=?,online_fulfillment_enabled=? WHERE id=?');$st->execute([...array_values($vals),$online,$id]);if(!$st->rowCount()&&!db()->prepare('SELECT 1 FROM locations WHERE id=?')->execute([$id]))throw new InvalidArgumentException('Location not found.');audit('LOCATION_UPDATE','location',$id);}}elseif($action==='fulfill'){$id=(int)$_POST['id'];db()->prepare('UPDATE locations SET online_fulfillment_enabled=1-online_fulfillment_enabled WHERE id=?')->execute([$id]);audit('LOCATION_FULFILL_TOGGLE','location',$id);}elseif($action==='toggle'){$id=(int)$_POST['id'];db()->prepare('UPDATE locations SET active=1-active WHERE id=?')->execute([$id]);audit('LOCATION_TOGGLE','location',$id);}redirect('locations.php');}catch(InvalidArgumentException $e){$err=$e->getMessage();}catch(Throwable $e){$err='Could not save location. Code may already exist.';}}
$rows=db()->query('SELECT * FROM locations ORDER BY code')->fetchAll();
$edit=null;$editId=(int)($_GET['edit']??($_POST['action']??'')==='update'?($_POST['id']??0):0);if($editId)foreach($rows as $r)if((int)$r['id']===$editId)$edit=$r;
$v=function(string $f)use($edit,$err){if($err&&isset($_POST[$f]))return (string)$_POST[$f];return (string)($edit[$f]??'');};
page_header('Godown / Rack Locations');if($err)echo '<div class="notice error">'.e($err).'</div>'; ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><div class="notice">Editing <b><?=e($edit['code'])?></b>. Stock already in this location stays here; only its address changes.</div><br><?php endif;?><div class="row3"><div><label>Location Code</label><input name="code" required placeholder="GDN-A-R03-S2-B02" value="<?=e($v('code'))?>"></div><div><label>Display Name</label><input name="name" required value="<?=e($v('name'))?>"></div><div><label>Warehouse / Godown</label><input name="warehouse" value="<?=e($v('warehouse'))?>"></div></div><br><div class="row3"><div><label>Floor</label><input name="floor_name" value="<?=e($v('floor_name'))?>"></div><div><label>Section</label><input name="section_name" value="<?=e($v('section_name'))?>"></div><div><label>Rack Number</label><input name="rack" value="<?=e($v('rack'))?>"></div></div><br><div class="row3"><div><label>Shelf Number</label><input name="shelf" value="<?=e($v('shelf'))?>"></div><div><label>Bin Number</label><input name="shelf_bin" value="<?=e($v('shelf_bin'))?>"></div><div><label><input type="checkbox" name="online_fulfillment_enabled" value="1" style="width:auto"<?=($edit?$edit['online_fulfillment_enabled']:0)?' checked':''?>> Online Fulfilment Enabled (reserve/pick/pack)</label></div></div><br><button class="btn"><?=$edit?'Save Location':'Add Location'?></button><?php if($edit):?> <a class="btn secondary" href="locations.php">Cancel</a><?php endif;?></form><br>
<table><tr><th>Code</th><th>Name</th><th>Godown</th><th>Floor</th><th>Section</th><th>Rack</th><th>Shelf</th><th>Bin</th><th>Online Fulfilment</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['name'])?></td><td><?=e($r['warehouse'])?></td><td><?=e($r['floor_name'])?></td><td><?=e($r['section_name'])?></td><td><?=e($r['rack'])?></td><td><?=e($r['shelf'])?></td><td><?=e($r['shelf_bin'])?></td><td><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="fulfill"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn secondary"><?=$r['online_fulfillment_enabled']?'Enabled':'Disabled'?></button></form></td><td><?= $r['active']?'Active':'Inactive' ?></td><td class="actions"><a class="btn secondary" href="locations.php?edit=<?=(int)$r['id']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn secondary"><?=$r['active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></table><?php page_footer();
